use crate::aap::caps::state_read;

struct Node;

/// Keys under which the subscription list may be stored. The store cannot be
/// enumerated, so the node asks only about names it already knows.
const KEYS: [&str; 4] = ["subscriptions", "urls", "feeds", "list"];

/// Pull every JSON string literal out of `src`, decoding escapes.
fn json_strings(src: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut chars = src.chars();
    while let Some(c) = chars.next() {
        if c != '"' {
            continue;
        }
        let mut s = String::new();
        let mut closed = false;
        while let Some(c) = chars.next() {
            match c {
                '"' => {
                    closed = true;
                    break;
                }
                '\\' => match chars.next() {
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('r') => s.push('\r'),
                    Some('b') => s.push('\u{8}'),
                    Some('f') => s.push('\u{c}'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        let mut ok = true;
                        for _ in 0..4 {
                            match chars.next().and_then(|h| h.to_digit(16)) {
                                Some(d) => code = code * 16 + d,
                                None => {
                                    ok = false;
                                    break;
                                }
                            }
                        }
                        if ok {
                            if let Some(ch) = char::from_u32(code) {
                                s.push(ch);
                            }
                        }
                    }
                    Some(other) => s.push(other),
                    None => break,
                },
                other => s.push(other),
            }
        }
        if closed {
            out.push(s);
        }
    }
    out
}

/// Parse a stored value into URLs. Accepts a JSON array of strings, a JSON
/// object containing URL strings, or plain text separated by newlines,
/// commas or whitespace (with `#` comments).
fn parse_urls(value: &str) -> Vec<String> {
    let trimmed = value.trim();
    let mut out: Vec<String> = Vec::new();

    if trimmed.starts_with('[') {
        for s in json_strings(trimmed) {
            let s = s.trim();
            if !s.is_empty() {
                out.push(s.to_string());
            }
        }
    } else if trimmed.starts_with('{') {
        for s in json_strings(trimmed) {
            let s = s.trim();
            if s.contains("://") {
                out.push(s.to_string());
            }
        }
    } else {
        for line in trimmed.lines() {
            let line = match line.find('#') {
                // Only treat '#' as a comment at line start or after whitespace,
                // so URL fragments survive.
                Some(0) => "",
                Some(i) if line[..i].ends_with(char::is_whitespace) => &line[..i],
                _ => line,
            };
            for part in line.split(|c: char| c == ',' || c == ';' || c.is_whitespace()) {
                let part = part.trim().trim_matches(|c| c == '"' || c == '\'');
                if !part.is_empty() {
                    out.push(part.to_string());
                }
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let mut urls: Vec<String> = Vec::new();

        for key in KEYS.iter() {
            if let Some(value) = state_read::get(key) {
                for url in parse_urls(&value) {
                    if !urls.contains(&url) {
                        urls.push(url);
                    }
                }
                if !urls.is_empty() {
                    break;
                }
            }
        }

        if urls.is_empty() {
            // The contract requires `urls` to be present; with nothing in the
            // store there is no honest output to give, so produce none.
            panic!("no subscriptions found in state store");
        }

        SubscriptionList { urls }
    }
}

export!(Node);
